Profression = require("Battle.Ply.Profression.Profression")
---@class PlayerProfressionManager
---@field player PlayerModel
local M = class("PlayerProfressionManager")

--初始化
function M:init(player, role_profression, role_profression_lv_data )
    self.player = player;
    --玩家职业
    self.role_profression = role_profression or 1;
    --玩家等级
    self.role_profression_lv = role_profression_lv_data.lv or 0;
    --英雄升级加属性配置
    self.herorole = ConfigManager:getCfgByName("herorole")
    if self.role_profression >= 6 then
        self.role_profression = 6
    end
    if self.role_profression <= 1 then
        self.role_profression = 1
    end
    if self.role_profression_lv >= 6 then
        self.role_profression_lv = 6;
    end
    if self.role_profression_lv <= 1 then
        self.role_profression_lv = 1
    end
    self.cur_hero_item = self.herorole[self.role_profression][self.role_profression_lv]
    if self.cur_hero_item ~= nil then
        if self.role_profression == 1 then
            --护卫
            self.profressionScript = require("Battle.Ply.Profression.ProfressionHuWei").new()
        elseif self.role_profression == 2 then
            --战士
            self.profressionScript = require("Battle.Ply.Profression.ProfressionZhanShi").new()
        elseif self.role_profression == 3 then
            --刺客
            self.profressionScript = require("Battle.Ply.Profression.ProfressionCiKe").new()
        elseif self.role_profression == 4 then
            --神射
            self.profressionScript = require("Battle.Ply.Profression.ProfressionShenShe").new()
        elseif self.role_profression == 5 then
            --辅助
            self.profressionScript = require("Battle.Ply.Profression.ProfressionFuZhu").new()
        elseif self.role_profression == 6 then
            --术士
            self.profressionScript = require("Battle.Ply.Profression.ProfressionShuShi").new()
        end
        if self.profressionScript ~= nil then
            self.profressionScript:init(self.player, self.cur_hero_item.param)
        end
    else
        Logger.logError(" 职业升级加属性 ~~~~ 配置没有找到 ")
    end
end

--游戏开始时
function M:gameStart()
    if self.profressionScript ~= nil then
        self.profressionScript:gameStart()
    end
end

--更新
function M:update( dt )
    --Logger.logError("玩家更新 ~~~~~~~~~~~~~~~~~~ ")
    if self.profressionScript ~= nil then
        self.profressionScript:update( dt )
    end
end

--攻击时
function M:Attack( attackData )
    if self.profressionScript ~= nil then
        self.profressionScript:Attack( attackData )
    end
end

--被攻击时
function M:BeHit( attackData )
    if self.profressionScript ~= nil then
        self.profressionScript:BeHit( attackData )
    end
end

--被攻击技术时
function M:BeHitOver()
    if self.profressionScript ~= nil then
        self.profressionScript:BeHitOver()
    end
end

--死亡之前的攻击
function M:attackBeforeDead(damage)
    if self.profressionScript ~= nil then
        return self.profressionScript:attackBeforeDead( damage )
    end
end

--释放大招开始
function M:skill3Start()
    --Logger.logError(self.player.plyType.." 释放大招开始 ~~~~~~~~~~~~~~~~~~ ")
    if self.profressionScript ~= nil then
        self.profressionScript:skill3Start()
    end
end

--释放大招结束
function M:skill3Over()
    --Logger.logError(self.player.plyType.." 释放大招结束 ~~~~~~~~~~~~~~~~~~ ")
    if self.profressionScript ~= nil then
        self.profressionScript:skill3Over()
    end
end

--游戏结束时
function M:gameOver()
    --Logger.logError(" 战斗结束时 ~~~~~~~~~~~~~~~~~~ ")
    if self.profressionScript ~= nil then
        self.profressionScript:gameOver()
    end
end

return M;